1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <meta name="description" content="A modern, accessible website built with best practices">
7	    <meta name="theme-color" content="#667eea">
8	    <meta property="og:title" content="Modern Web Template">
9	    <meta property="og:description" content="A modern, accessible website built with best practices">
10	    <meta property="og:type" content="website">
11	    <meta name="author" content="Web Developer">
12	    <meta name="keywords" content="html, template, modern, accessible, responsive">
13	    <meta property="og:image" content="https://via.placeholder.com/1200x630?text=Modern+Web+Template">
14	    <meta property="og:url" content="https://example.com/">
15	    <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='75' font-size='75' fill='%23667eea'>W</text></svg>">
16	    <title>Welcome | Modern Web Template</title>
17	    <style>
18	        :root {
19	            --primary-gradient: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
20	            --primary-color: #667eea;
21	            --text-color: #2c3e50;
22	            --bg-color: #f8f9fa;
23	            --focus-color: #667eea;
24	        }
25	
26	        html {
27	            scroll-behavior: smooth;
28	        }
29	
30	        * {
31	            margin: 0;
32	            padding: 0;
33	            box-sizing: border-box;
34	        }
35	
36	        body {
37	            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
38	            line-height: 1.6;
39	            background-color: var(--bg-color);
40	            color: var(--text-color);
41	        }
42	
43	        a:focus-visible,
44	        button:focus-visible {
45	            outline: 3px solid var(--focus-color);
46	            outline-offset: 2px;
47	        }
48	
49	        .skip-link {
50	            position: absolute;
51	            top: -40px;
52	            left: 0;
53	            background: #667eea;
54	            color: white;
55	            padding: 8px 16px;
56	            text-decoration: none;
57	            z-index: 100;
58	        }
59	
60	        .skip-link:focus-visible {
61	            top: 0;
62	        }
63	
64	        header {
65	            background: var(--primary-gradient);
66	            color: white;
67	            padding: 3rem 20px;
68	            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
69	        }
70	
71	        header h1 {
72	            max-width: 1200px;
73	            margin: 0 auto;
74	            font-size: 2.5rem;
75	            font-weight: 600;
76	        }
77	
78	        main {
79	            max-width: 1200px;
80	            margin: 0 auto;
81	            padding: 40px 20px;
82	        }
83	
84	        article {
85	            margin-bottom: 3rem;
86	        }
87	
88	        h2 {
89	            color: var(--primary-color);
90	            margin-bottom: 1rem;
91	            font-size: 1.8rem;
92	        }
93	
94	        p {
95	            margin-bottom: 1rem;
96	            font-size: 1.05rem;
97	            line-height: 1.8;
98	        }
99	
100	        .cta-button {
101	            display: inline-block;
102	            background: var(--primary-gradient);
103	            color: white;
104	            padding: 12px 32px;
105	            border: none;
106	            border-radius: 6px;
107	            font-size: 1rem;
108	            cursor: pointer;
109	            text-decoration: none;
110	            transition: transform 0.2s, box-shadow 0.2s;
111	        }
112	
113	        .cta-button:hover {
114	            transform: translateY(-2px);
115	            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
116	        }
117	
118	        .cta-button:active {
119	            transform: translateY(0);
120	        }
121	
122	        .cta-button:focus-visible {
123	            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
124	        }
125	
126	        @media (prefers-reduced-motion: reduce) {
127	            html {
128	                scroll-behavior: auto;
129	            }
130	
131	            * {
132	                animation-duration: 0.01ms !important;
133	                animation-iteration-count: 1 !important;
134	                transition-duration: 0.01ms !important;
135	            }
136	        }
137	
138	        footer {
139	            background-color: #2c3e50;
140	            color: white;
141	            padding: 2rem 20px;
142	            text-align: center;
143	            margin-top: 3rem;
144	        }
145	
146	        footer p {
147	            margin: 0 0 1rem 0;
148	            font-size: 0.95rem;
149	            opacity: 0.8;
150	        }
151	
152	        footer a {
153	            color: #667eea;
154	            text-decoration: none;
155	        }
156	
157	        footer a:hover,
158	        footer a:focus-visible {
159	            text-decoration: underline;
160	        }
161	
162	        .feature-list {
163	            margin-left: 20px;
164	            margin-bottom: 1rem;
165	        }
166	
167	        .feature-list li {
168	            margin-bottom: 0.5rem;
169	            padding-left: 0.5rem;
170	        }
171	
172	        .feature-list li::marker {
173	            color: var(--primary-color);
174	            font-weight: 600;
175	        }
176	
177	        @media (prefers-color-scheme: dark) {
178	            :root {
179	                --bg-color: #1a1a1a;
180	                --text-color: #e0e0e0;
181	            }
182	
183	            h2 {
184	                color: #a8b9ff;
185	            }
186	
187	            footer {
188	                background-color: #0d0d0d;
189	            }
190	
191	            footer a {
192	                color: #a8b9ff;
193	            }
194	
195	            .feature-list li {
196	                color: #c0c0c0;
197	            }
198	        }
199	
200	        @media (max-width: 768px) {
201	            header h1 {
202	                font-size: 2rem;
203	            }
204	
205	            h2 {
206	                font-size: 1.5rem;
207	            }
208	
209	            p {
210	                font-size: 1rem;
211	            }
212	        }
213	    </style>
214	</head>
215	<body>
216	    <a href="#main-content" class="skip-link">Skip to main content</a>
217	
218	    <header>
219	        <h1>Welcome</h1>
220	    </header>
221	
222	    <main id="main-content">
223	        <article>
224	            <h2>Modern Web Template</h2>
225	            <p>This is an improved HTML template built with best practices for performance, accessibility, and maintainability.</p>
226	        </article>
227	
228	        <article id="features">
229	            <h2>Key Features</h2>
230	            <p>
231	                This template includes semantic HTML elements, responsive design, modern CSS with gradients,
232	                proper meta tags for SEO, and accessibility considerations to create a solid foundation for any web project.
233	            </p>
234	            <ul class="feature-list">
235	                <li>Semantic HTML5 structure</li>
236	                <li>WCAG 2.1 accessibility compliance</li>
237	                <li>Mobile-first responsive design</li>
238	                <li>Keyboard navigation support</li>
239	                <li>Open Graph meta tags</li>
240	            </ul>
241	        </article>
242	
243	        <article>
244	            <h2>Get Started</h2>
245	            <p>
246	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
247	                customized to meet your specific needs.
248	            </p>
249	            <button type="button" class="cta-button" aria-label="Learn more about the modern web template">Learn More</button>
250	        </article>
251	    </main>
252	
253	    <footer>
254	        <p>&copy; 2026 Modern Web Template. All rights reserved.</p>
255	        <nav aria-label="Footer links">
256	            <p>
257	                <a href="/privacy/">Privacy Policy</a> |
258	                <a href="/terms/">Terms of Service</a>
259	            </p>
260	        </nav>
261	    </footer>
262	
263	    <script type="application/ld+json">
264	    {
265	        "@context": "https://schema.org",
266	        "@type": "WebSite",
267	        "name": "Modern Web Template",
268	        "description": "A modern, accessible website built with best practices"
269	    }
270	    </script>
271	
272	    <script>
273	        document.addEventListener('DOMContentLoaded', function() {
274	            const learnMoreBtn = document.querySelector('.cta-button');
275	            if (learnMoreBtn) {
276	                learnMoreBtn.addEventListener('click', function() {
277	                    const featuresSection = document.getElementById('features');
278	                    if (featuresSection) {
279	                        featuresSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
280	                        featuresSection.querySelector('h2').focus();
281	                    }
282	                });
283	            }
284	        });
285	    </script>
286	</body>
287	</html>
